/**
 * src/search.mjs — independent catalog search/filter module.
 *
 * Public contract (README.md):
 *   searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {})
 *     - case-insensitive substring search on `name`
 *     - inclusive price bounds
 *     - preserves input order
 *     - never mutates the input array or the item objects
 *     - rejects invalid bounds
 *
 * This module is dependency-free: no imports, no runtime deps, no network,
 * and it deliberately does NOT depend on src/csv.mjs (parallel workstream).
 */

/** Format a value for an error message without ever throwing on weird input. */
function describe(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  if (typeof value === 'object') {
    const ctor = value.constructor && value.constructor.name;
    return `an object (${typeof ctor === 'string' && ctor !== 'Object' ? ctor : 'Object'})`;
  }
  return `${typeof value} ${String(value)}`;
}

/**
 * Validate a single numeric bound.
 *
 * @param {string} name  option name, used in error messages
 * @param {unknown} value
 * @param {boolean} allowPositiveInfinity  only `maxPrice` may be Infinity
 */
function assertBound(name, value, { allowPositiveInfinity }) {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    throw new TypeError(
      `searchCatalog: ${name} must be a number, received ${describe(value)}`,
    );
  }
  if (value < 0) {
    throw new RangeError(
      `searchCatalog: ${name} must not be negative, received ${value}`,
    );
  }
  if (!Number.isFinite(value) && !allowPositiveInfinity) {
    throw new RangeError(
      `searchCatalog: ${name} must be a finite number, received ${value}`,
    );
  }
}

/** Validate every option that influences matching. Returns the normalized filter. */
function normalizeOptions(query, minPrice, maxPrice) {
  if (typeof query !== 'string') {
    throw new TypeError(
      `searchCatalog: query must be a string, received ${describe(query)}`,
    );
  }
  assertBound('minPrice', minPrice, { allowPositiveInfinity: false });
  assertBound('maxPrice', maxPrice, { allowPositiveInfinity: true });
  if (minPrice > maxPrice) {
    throw new RangeError(
      `searchCatalog: invalid price bounds, minPrice (${minPrice}) exceeds maxPrice (${maxPrice})`,
    );
  }
  return { needle: query.toLowerCase(), minPrice, maxPrice };
}

/**
 * A catalog item is filterable only if it is an object exposing a string
 * `name` and a comparable numeric `price`. Anything else is simply not a
 * match (we do not throw, and we never touch the item).
 */
function isMatchable(item) {
  return (
    item !== null &&
    typeof item === 'object' &&
    typeof item.name === 'string' &&
    typeof item.price === 'number' &&
    !Number.isNaN(item.price)
  );
}

/**
 * Filter a catalog by a case-insensitive substring of `name` plus an
 * inclusive price window, preserving input order.
 *
 * @template {object} T
 * @param {readonly T[]} items           catalog rows (never mutated)
 * @param {object} [options]
 * @param {string} [options.query='']    substring searched in `name`, case-insensitive
 * @param {number} [options.minPrice=0]  inclusive lower price bound
 * @param {number} [options.maxPrice=Infinity] inclusive upper price bound
 * @returns {T[]} new array holding references to the matching input items
 */
export function searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {}) {
  if (!Array.isArray(items)) {
    throw new TypeError(
      `searchCatalog: items must be an array, received ${describe(items)}`,
    );
  }

  const { needle, minPrice: low, maxPrice: high } = normalizeOptions(query, minPrice, maxPrice);
  const matches = [];

  for (const item of items) {
    if (!isMatchable(item)) continue;
    if (needle !== '' && !item.name.toLowerCase().includes(needle)) continue;
    if (item.price < low || item.price > high) continue;
    matches.push(item);
  }

  return matches;
}

export default searchCatalog;

/**
 * tests/search.test.mjs — unit tests for src/search.mjs.
 *
 * Uses only Node's built-in test runner (`node --test`), which discovers this
 * file via the `*.test.mjs` pattern. No third-party deps, no network, and no
 * dependency on the parallel CSV workstream (src/csv.mjs / tests/csv.test.mjs).
 */

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { searchCatalog } from '../src/search.mjs';

/* ------------------------------------------------------------------ helpers */

/** Fixture factory: a fresh array of fresh objects for every test. */
function fixtures() {
  return [
    { id: '1', name: 'Green Tea', price: 3.5 },
    { id: '2', name: 'green coffee', price: 12 },
    { id: '3', name: 'Earl GREY', price: 8.25 },
    { id: '4', name: 'Matcha Powder', price: 0 },
    { id: '5', name: 'Olive Oil', price: 100 },
  ];
}

const names = (rows) => rows.map((r) => r.name);
const clone = (rows) => rows.map((r) => ({ ...r }));

/** Snapshot every observable mutation channel on the input. */
function mutationGuard(rows) {
  const snapshot = JSON.stringify(rows);
  return {
    assertClean(label = 'input') {
      assert.equal(JSON.stringify(rows), snapshot, `${label}: array contents were mutated`);
      assert.ok(Array.isArray(rows), `${label}: array was replaced`);
    },
  };
}

/* --------------------------------------------------------------- signature */

test('searchCatalog is exported as a function of arity 2', () => {
  assert.equal(typeof searchCatalog, 'function');
  // (items, options) — rest not required; default `= {}` keeps arity at 2.
  assert.equal(searchCatalog.length, 2);
});

test('second argument is optional (omitted entirely)', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items)), names(items));
});

test('options may be an empty object, applying all documented defaults', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, {})), names(items));
});

test('defaults are query="", minPrice=0, maxPrice=Infinity (per README)', () => {
  const items = fixtures();

  // minPrice defaults to 0: a 0-priced item survives, a negative-priced one does not.
  const withNegatives = [
    { id: 'n', name: 'Refund', price: -1 },
    { id: 'z', name: 'Sample', price: 0 },
  ];
  assert.deepEqual(names(searchCatalog(withNegatives)), ['Sample']);
  assert.deepEqual(names(searchCatalog(withNegatives, { minPrice: 0 })), ['Sample']);

  // maxPrice defaults to Infinity: huge prices survive with only minPrice given.
  const expensive = [{ id: 'e', name: 'Telescope', price: Number.MAX_VALUE }];
  assert.deepEqual(names(searchCatalog(expensive, { minPrice: 10 })), ['Telescope']);
  assert.deepEqual(names(searchCatalog(expensive, { minPrice: 10, maxPrice: Infinity })), [
    'Telescope',
  ]);

  // query defaults to '': no name filtering.
  assert.equal(searchCatalog(items, { minPrice: 1 }).length, 4);
  assert.deepEqual(searchCatalog(items, { query: '' }), searchCatalog(items, { query: undefined }));
});

test('undefined option values fall back to the documented defaults', () => {
  const items = fixtures();
  const explicit = searchCatalog(items, {
    query: undefined,
    minPrice: undefined,
    maxPrice: undefined,
  });
  assert.deepEqual(names(explicit), names(items));
});

/* ---------------------------------------------------------- name matching */

test('name matching is case-insensitive in both directions', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { query: 'GREEN' })), [
    'Green Tea',
    'green coffee',
  ]);
  assert.deepEqual(names(searchCatalog(items, { query: 'green' })), ['Green Tea', 'green coffee']);
  assert.deepEqual(names(searchCatalog(items, { query: 'GrEy' })), ['Earl GREY']);
});

test('matching is a substring test, not a prefix or word test', () =>
  assert.deepEqual(names(searchCatalog(fixtures(), { query: 'at' })), ['Matcha Powder']));

test('query containing spaces matches inside names', () => {
  assert.deepEqual(names(searchCatalog(fixtures(), { query: 'Green ' })), ['Green Tea']);
});

test('whitespace-only query is not treated as empty', () => {
  assert.deepEqual(names(searchCatalog(fixtures(), { query: ' ' })), ['Earl GREY']);
});

test('a query that matches nothing returns an empty array', () => {
  const result = searchCatalog(fixtures(), { query: 'zzz' });
  assert.ok(Array.isArray(result));
  assert.equal(result.length, 0);
});

test('search only looks at `name` (not id, not numeric price text)', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { query: 'id' })), []);
  assert.deepEqual(searchCatalog(items, { query: '100' }), []);
  assert.deepEqual(searchCatalog(items, { query: '3.5' }), []);
});

test('regex metacharacters in the query are literal', () => {
  const items = [
    { id: '1', name: 'A.B', price: 1 },
    { id: '2', name: 'AXB', price: 1 },
  ];
  assert.deepEqual(names(searchCatalog(items, { query: 'A.B' })), ['A.B']);
  assert.deepEqual(names(searchCatalog(items, { query: '.' })), ['A.B', 'AXB']);
});

/* ------------------------------------------------------------ price bounds */

test('price bounds are inclusive on both ends', () => {
  const items = [{ id: '1', name: 'Thing', price: 10 }];
  assert.equal(searchCatalog(items, { minPrice: 10 }).length, 1);
  assert.equal(searchCatalog(items, { maxPrice: 10 }).length, 1);
  assert.equal(searchCatalog(items, { minPrice: 10, maxPrice: 10 }).length, 1);
  assert.equal(searchCatalog(items, { minPrice: 10.01 }).length, 0);
  assert.equal(searchCatalog(items, { maxPrice: 9.99 }).length, 0);
});

test('bounds window filters correctly and keeps order', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { minPrice: 3.5, maxPrice: 100 })), [
    'Green Tea',
    'Earl GREY',
    'Olive Oil',
  ]);
  assert.deepEqual(names(searchCatalog(items, { minPrice: 8, maxPrice: 12 })), [
    'green coffee',
    'Earl GREY',
  ]);
});

test('fractional bounds work with floating point prices', () => {
  const items = [
    { id: '1', name: 'Under', price: 4.999 },
    { id: '2', name: 'Exact', price: 5 },
    { id: '3', name: 'Over', price: 5.001 },
  ];
  assert.deepEqual(names(searchCatalog(items, { minPrice: 5, maxPrice: 5 })), ['Exact']);
  assert.deepEqual(names(searchCatalog(items, { maxPrice: 5 })), ['Under', 'Exact']);
});

test('maxPrice=Infinity includes everything above minPrice', () => {
  const items = [{ id: '1', name: 'Astronomical', price: 1e308 }];
  assert.deepEqual(names(searchCatalog(items, { minPrice: 0, maxPrice: Infinity })), [
    'Astronomical',
  ]);
});

test('query and bounds combine (logical AND)', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { query: 'e', minPrice: 5, maxPrice: 50 })), [
    'green coffee',
    'Earl GREY',
  ]);
});

/* ------------------------------------------------------- order and safety */

test('input order is preserved even when output order differs from sorted', () => {
  const items = [
    { id: 'a', name: 'Zebra Cake', price: 30 },
    { id: 'b', name: 'Apple Cake', price: 10 },
    { id: 'c', name: 'Kiwi Cake', price: 20 },
  ];
  assert.deepEqual(names(searchCatalog(items, { query: 'Cake' })), [
    'Zebra Cake',
    'Apple Cake',
    'Kiwi Cake',
  ]);
});

test('the input array and its items are never mutated', () => {
  const items = fixtures();
  const before = clone(items);
  const guard = mutationGuard(items);
  const originalLength = items.length;
  const originalArray = items;

  const result = searchCatalog(items, { query: 'n', minPrice: 1, maxPrice: 50 });

  assert.equal(items, originalArray, 'items argument reference untouched');
  assert.equal(items.length, originalLength, 'array length unchanged');
  guard.assertClean();
  assert.deepEqual(items, before);
  assert.notEqual(result, items, 'result is a new array');
});

test('a mutation-observing proxy confirms only reads happen', () => {
  const seen = { set: 0, delete: 0, define: 0 };
  const rows = [
    { id: '1', name: 'Green Tea', price: 3.5 },
    { id: '2', name: 'Olive Oil', price: 100 },
  ];
  const watchedArray = new Proxy(rows, {
    set(t, p, v) {
      seen.set += 1;
      t[p] = v;
      return true;
    },
    deleteProperty(t, p) {
      seen.delete += 1;
      delete t[p];
      return true;
    },
    defineProperty(t, p, d) {
      seen.define += 1;
      Object.defineProperty(t, p, d);
      return true;
    },
  });
  const watchedItems = rows.map(
    (row) =>
      new Proxy(row, {
        set(t, p, v) {
          seen.set += 1;
          t[p] = v;
          return true;
        },
        deleteProperty(t, p) {
          seen.delete += 1;
          delete t[p];
          return true;
        },
        defineProperty(t, p, d) {
          seen.define += 1;
          Object.defineProperty(t, p, d);
          return true;
        },
      }),
  );

  const result = searchCatalog(watchedArray, { query: 'OIL', minPrice: 10 });
  assert.deepEqual(names(watchedItems), ['Green Tea', 'Olive Oil']);
  assert.equal(result.length, 1);
  assert.deepEqual(seen, { set: 0, delete: 0, define: 0 });

  // Item objects are also untouched when only bounds filter.
  searchCatalog(watchedItems, { maxPrice: 50 });
  assert.equal(seen.set, 0);
});

test('frozen input (array and items) is accepted, proving no writes are attempted', () => {
  const items = Object.freeze([
    Object.freeze({ id: '1', name: 'Green Tea', price: 3.5 }),
    Object.freeze({ id: '2', name: 'Olive Oil', price: 100 }),
  ]);
  assert.deepEqual(names(searchCatalog(items, { query: 'tea' })), ['Green Tea']);
  assert.deepEqual(names(searchCatalog(items)), ['Green Tea', 'Olive Oil']);
});

test('result holds references to the original items, not copies', () => {
  const items = fixtures();
  const result = searchCatalog(items, { query: 'Tea' });
  assert.equal(result.length, 1);
  assert.equal(result[0], items[0]);
});

test('mutating the result does not affect the input (and vice versa)', () => {
  const items = fixtures();
  const before = clone(items);
  const result = searchCatalog(items, { query: 'e' });
  result.push({ id: 'x', name: 'Injected', price: 1 });
  result[0] = null;
  assert.deepEqual(items, before);
});

test('extra/unknown properties on items are ignored and preserved by reference', () => {
  const items = [
    { id: '1', name: 'Green Tea', price: 3.5, tags: ['a'], stock: 4 },
    { id: '2', name: 'Kettle', price: 3.5 },
  ];
  const result = searchCatalog(items, { minPrice: 3.5, maxPrice: 3.5 });
  assert.equal(result[0], items[0]);
  assert.deepEqual(result[0].tags, ['a']);
});

test('empty input returns an empty array', () => {
  assert.deepEqual(searchCatalog([]), []);
  assert.deepEqual(searchCatalog([], { query: 'anything' }), []);
});

test('items with unusable name/price are skipped rather than crashing', () => {
  const items = [
    { id: '1', name: 'Good', price: 5 },
    { id: '2', price: 5 }, // no name
    { id: '3', name: 'No Price' }, // no price
    { id: '4', name: 42, price: 5 }, // non-string name
    { id: '5', name: 'String Price', price: '5' }, // non-number price
    { id: '6', name: 'NaN Price', price: Number.NaN },
    { id: '7', name: null, price: 5 },
    null,
    undefined,
    'not an object',
  ];
  assert.deepEqual(names(searchCatalog(items)), ['Good']);
  assert.deepEqual(names(searchCatalog(items, { query: 'o' })), ['Good']);
});

/* -------------------------------------------------------- bound validation */

test('non-array items are rejected with a TypeError', () => {
  for (const bad of [undefined, null, 'Green Tea', 42, {}, new Set(), new Map()]) {
    assert.throws(
      () => searchCatalog(bad, { query: 'tea' }),
      (err) => err instanceof TypeError && /items must be an array/i.test(err.message),
      `expected TypeError for items=${String(bad)}`,
    );
  }
});

test('non-string query is rejected with a TypeError', () => {
  for (const bad of [0, NaN, true, null, {}, ['tea'], () => {}]) {
    assert.throws(
      () => searchCatalog(fixtures(), { query: bad }),
      (err) => err instanceof TypeError && /query must be a string/i.test(err.message),
      `expected TypeError for query=${String(bad)}`,
    );
  }
});

test('non-numeric bounds are rejected with a TypeError', () => {
  for (const bad of ['10', '', true, false, null, {}, [], Symbol('n'), () => {}]) {
    assert.throws(
      () => searchCatalog(fixtures(), { minPrice: bad }),
      (err) => err instanceof TypeError && /minPrice must be a number/i.test(err.message),
      `expected TypeError for minPrice=${String(bad)}`,
    );
    assert.throws(
      () => searchCatalog(fixtures(), { maxPrice: bad }),
      (err) => err instanceof TypeError && /maxPrice must be a number/i.test(err.message),
      `expected TypeError for maxPrice=${String(bad)}`,
    );
  }
});

test('NaN bounds are rejected', () => {
  assert.throws(() => searchCatalog(fixtures(), { minPrice: Number.NaN }), TypeError);
  assert.throws(() => searchCatalog(fixtures(), { maxPrice: Number.NaN }), TypeError);
});

test('negative bounds are rejected with a RangeError', () => {
  assert.throws(
    () => searchCatalog(fixtures(), { minPrice: -0.01 }),
    (err) => err instanceof RangeError && /minPrice must not be negative/i.test(err.message),
  );
  assert.throws(
    () => searchCatalog(fixtures(), { maxPrice: -1 }),
    (err) => err instanceof RangeError && /maxPrice must not be negative/i.test(err.message),
  );
  assert.throws(() => searchCatalog(fixtures(), { maxPrice: Number.NEGATIVE_INFINITY }), RangeError);
});

test('-Infinity minPrice is rejected, +Infinity minPrice is rejected too', () => {
  assert.throws(() => searchCatalog(fixtures(), { minPrice: Number.NEGATIVE_INFINITY }), RangeError);
  assert.throws(
    () => searchCatalog(fixtures(), { minPrice: Number.POSITIVE_INFINITY }),
    (err) => err instanceof RangeError && /minPrice must be a finite number/i.test(err.message),
  );
});

test('minPrice greater than maxPrice is rejected', () => {
  assert.throws(
    () => searchCatalog(fixtures(), { minPrice: 20, maxPrice: 10 }),
    (err) => err instanceof RangeError && /minPrice \(20\) exceeds maxPrice \(10\)/i.test(err.message),
  );
  assert.throws(() => searchCatalog(fixtures(), { minPrice: 10.5, maxPrice: 10.4 }), RangeError);
  assert.throws(
    () => searchCatalog(fixtures(), { minPrice: 1, maxPrice: 1 - Number.EPSILON }),
    RangeError,
  );
});

test('equal bounds are valid (point query)', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { minPrice: 12, maxPrice: 12 })), ['green coffee']);
  assert.deepEqual(names(searchCatalog(items, { minPrice: 0, maxPrice: 0 })), ['Matcha Powder']);
});

test('validation happens before filtering (no partial work, input untouched)', () => {
  const items = fixtures();
  const before = clone(items);
  assert.throws(() => searchCatalog(items, { minPrice: -5 }), RangeError);
  assert.deepEqual(items, before);
});

/* ------------------------------------------------------------ independence */

test('module source imports nothing and never references the CSV workstream', () => {
  const source = readFileSync(fileURLToPath(new URL('../src/search.mjs', import.meta.url)), 'utf8');
  assert.equal(/(^|\n)\s*import[\s\S]*?from/.test(source), false, 'no static imports allowed');
  assert.equal(/\brequire\s*\(/.test(source), false, 'no require() allowed');
  assert.equal(/node:/.test(source.replace(/^\/\/.*$/gm, '').replace(/\*[\s\S]*?\*\//g, '')), false);
  assert.equal(/csv/i.test(source), false, 'search.mjs must not depend on csv');
});

test('search results are usable as plain rows (interop-ready shape)', () => {
  const rows = [
    { id: '1', name: 'Green Tea', price: 3.5 },
    { id: '2', name: 'Olive Oil', price: 100 },
  ];
  const found = searchCatalog(rows, { query: 'oil', minPrice: 10, maxPrice: 1000 });
  assert.deepEqual(found, [{ id: '2', name: 'Olive Oil', price: 100 }]);
  assert.deepEqual(Object.keys(found[0]).sort(), ['id', 'name', 'price']);
});

