    },
  });

  const hit = makeRow('Green Tea');
  const miss = makeRow('Olive Oil');
  const result = searchCatalog([hit, miss], { query: 'tea', minPrice: 1, maxPrice: 5 });

  assert.equal(result.length, 1);
  assert.equal(result[0], hit);
  assert.deepEqual(reads, { name: 2, price: 1 }, 'price of a name-mismatched row is never read');
});

